from docx import Document
from docx.oxml.ns import qn
doc = Document('/app/Interview_Assessment_Report_John_Smith.docx')
tbl = doc.tables[0]
for i, row in enumerate(tbl.rows):
    for j, cell in enumerate(row.cells):
        print(f'Cell [{i},{j}]: text=\"{cell.text}\"')
        tc = cell._element
        tcPr = tc.find(qn('w:tcPr'))
        if tcPr is not None:
            shd = tcPr.find(qn('w:shd'))
            if shd is not None:
                print(f'  shading: fill={shd.get(qn(\"w:fill\"))}')
        vAlign = tc.find(qn('w:vAlign'))
        if vAlign is not None:
            print(f'  vAlign: {vAlign.get(qn(\"w:val\"))}')
        for p in cell.paragraphs:
            print(f'  pAlign: {p.alignment}')
"
